27:     internal static bool TryHandleChatCommand(string message)
28:     {
29:         string text = message.Trim();
30:         if (!IsAiCommand(text))
31:         {
32:             int idx = message.IndexOf(": ", StringComparison.Ordinal);
33:             if (idx < 0) return false;
34:             text = message.Substring(idx + 2).Trim();
35:             if (!IsAiCommand(text))
36:             {
37:                 // not a command: a line with an @mention also goes to those members' upper LLM; the line itself is sent
38:                 // to the other players as ordinary chat either way (자연어 명령 합의 1)
39:                 try { TryHandleMention(text); } catch (Exception e) { LogError("mention handling failed", e); }
40:                 return false;
41:             }
42:         }
43:         if (!InHostedGame(out World server))
44:         {
45:             return false; // not our world (joined someone else's): leave the message alone
46:         }
47:         string[] parts = text.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
48:         Log($"chat command from host: '{text}'");
49:         if (WorldId == null)
50:         {
51:             Reply("AI: 아직 월드 정보를 읽는 중입니다. 잠시 뒤 다시 입력하세요.");
52:             return true;
53:         }
54:         // Which character: "/ai <member> <cmd ...>" (claude | gpt | gemini | grok, names too) or "/ai all <cmd>";
55:         // also "/ai on|off <member>". Without a member: the default character (Claude when it is in the world, else
56:         // the first character in the world); "/ai off" without a member turns every character off; "/ai" alone
57:         // shows every member.
58:         var targets = new List<AIAgent>();
59:         bool all = false;
60:         if (parts.Length > 1)
61:         {
62:             if (IsAll(parts[1])) { all = true; parts = Without(parts, 1); }
63:             else { var a = AIAgent.Find(parts[1]); if (a != null) { targets.Add(a); parts = Without(parts, 1); } }
64:         }
65:         string arg = parts.Length > 1 ? parts[1].ToLowerInvariant() : "status";
66:         bool onOff = arg == "on" || arg == "켜기" || arg == "off" || arg == "끄기";
67:         if (targets.Count == 0 && !all && onOff && parts.Length > 2)
68:         {
69:             if (IsAll(parts[2])) all = true;
70:             else { var a = AIAgent.Find(parts[2]); if (a != null) targets.Add(a); }
71:         }
72:         if (all) { targets.Clear(); targets.AddRange(AIAgent.All); }
73:         if (targets.Count == 0)
74:         {
75:             if (arg == "status" || arg == "상태") { Reply(StatusAll()); return true; }
76:             // stop and "goal 없음" without a member stop every member too (검수 F3, HEAD decision): members go on with
77:             // goals of their own (합의 3d), so stopping only the default one left the others running
78:             bool stopAll = arg == "stop" || arg == "멈춤" || ((arg == "goal" || arg == "목표") && parts.Length > 2 && AIGoals.IsNoGoalWord(parts[2]));
79:             if (arg == "off" || arg == "끄기" || stopAll) { foreach (var a in AIAgent.All) if (arg == "off" || arg == "끄기" || IsJoined(a)) targets.Add(a); }
80:             else targets.Add(DefaultAgent());
81:         }
82:         int order = 0;
83:         foreach (var a in targets)
84:         {
85:             // with "all", commands other than on/off go only to characters that are in the world
86:             if (all && !onOff && !IsJoined(a)) continue;
87:             using (AIAgent.Enter(a))
88:             {
89:                 try { Dispatch(server, arg, parts, order++); }
90:                 catch (Exception e) { LogError($"chat command for {a.Name} failed", e); }
91:             }
92:         }
93:         return true;
94:     }

241:     private static string StatusAll()
242:     {
243:         var l = new List<string>();
244:         foreach (var a in AIAgent.All)
245:             using (AIAgent.Enter(a))
246:             {
247:                 bool on = AIWorldSettings.Members(WorldId).Contains(a.Id);
248:                 l.Add($"{a.Name} {(on ? "켜짐" : "꺼짐")}/{StageText()}{(_stage == Stage.Walking ? "/" + AIBrain.Goal.Text : "")}");
249:             }
250:         return "AI: " + string.Join(" · ", l) + " · 명령: /ai <멤버> on|off|goal …";
251:     }

218:     private static string StageText()
219:     {
220:         switch (_stage)
221:         {
222:             case Stage.Disabled: return "들어와 있지 않음";
223:             case Stage.CountingDown: return "곧 들어옴";
224:             case Stage.ThinWorldCreated:
225:             case Stage.Connected:
226:             case Stage.Accepted:
227:             case Stage.StartGameSent: return "들어오는 중";
228:             case Stage.PlayerSpawned:
229:             case Stage.Walking: return "들어와 있음";
230:             case Stage.Stopped: return "오류로 멈춤, 로그 확인";
231:             default: return _stage.ToString();
232:         }
233:     }

33:     public static List<string> Members(string worldId)
34:     {
35:         var l = new List<string>();
36:         if (worldId == null) return l;
37:         string p = PathFor(worldId);
38:         try
39:         {
40:             if (!File.Exists(p)) return l;
41:             string text = File.ReadAllText(p, Encoding.UTF8);
42:             var d = JsonUtility.FromJson<Data>(text);
43:             if (d == null) return l;
44:             bool hasMembers = text.IndexOf("\"members\"", StringComparison.Ordinal) >= 0;
45:             if (hasMembers && d.members != null) { foreach (var m in d.members) if (AIAgent.ById(m) != null && !l.Contains(m)) l.Add(m); }
46:             else if (!hasMembers && d.aiEnabled) l.Add("claude");   // file from before members
47:         }
48:         catch (Exception e)
49:         {
50:             AIPlayerSpikeMod.LogError($"AI setting: reading {p} failed; treating as off", e);
51:         }
52:         return l;
53:     }

81:     public static string PathFor(string worldId)
82:     {
83:         return Path.Combine(Application.persistentDataPath, "AIPlayers", worldId, "settings.json");
84:     }

