252:     internal static void Reply(string msg, ChatKind kind = ChatKind.Command, string repeatKey = null)
253:     {
254:         var who = AIAgent.InScope;
255:         if (who != null && !msg.StartsWith("[") && (who.Index != 0 || Joined().Count > 1)) msg = $"[{who.Name}] " + msg;
256:         msg = ChatPolicy.FontSafe(msg);   // the game font has no arrows (실게임2 N5)
257:         if (!ChatPolicy.Show(kind, AIBrain.Verbose)) { Log("chat hidden (status): " + msg); return; }
258:         if (repeatKey != null && !_repeatGate.Allow((who?.Id ?? "-") + "|" + repeatKey, Time.realtimeSinceStartup)) { Log("chat hidden (same notice within 5 min): " + msg); return; }
259:         Log("chat reply: " + msg);
260:         _pendingReplies.Enqueue(msg);
261:     }

226:     public void Update()
227:     {
228:         bool hosted = false;
229:         World server = null;
230:         try { hosted = InHostedGame(out server); } catch (Exception e) { LogError("hosted-game check failed", e); }
231:         // Every member has its own state machine; members that are off just sit in Stage.Disabled.
232:         foreach (var a in AIAgent.All)
233:         {
234:             using (AIAgent.Enter(a))
235:             {
236:                 long t0 = System.Diagnostics.Stopwatch.GetTimestamp();
237:                 try
238:                 {
239:                     Tick(hosted, server);
240:                 }
241:                 catch (Exception e)
242:                 {
243:                     LogError($"exception in stage {_stage}; stopping this character", e);
244:                     SetStage(Stage.Stopped);
245:                 }
246:                 if (_stage == Stage.Walking)
247:                 {
248:                     double ms = (System.Diagnostics.Stopwatch.GetTimestamp() - t0) * 1000.0 / System.Diagnostics.Stopwatch.Frequency;
249:                     a.TickMsSum += ms; a.TickN++; if (ms > a.TickMsMax) a.TickMsMax = ms;
250:                 }
251:             }
252:         }
253:         try { AIChatHint.Frame(hosted); } catch (Exception e) { LogError("chat hint failed", e); }   // hint only in our own world (검수 작은 지적 5)
254:         try { AIChatScreenLayer.Frame(hosted); } catch (Exception e) { LogError("chat screen layer failed", e); }
255:         try { AIInfoPanel.Frame(hosted, server); } catch (Exception e) { LogError("AI info UI failed", e); }
256:         if (hosted)
257:         {
258:             FlushReplies();
259:             try { AIPerf.Frame(server); } catch (Exception e) { LogError("perf sample failed", e); }
260:         }
261:     }

263:     private static void FlushReplies()
264:     {
265:         while (_pendingReplies.Count > 0)
266:         {
267:             string msg = _pendingReplies.Dequeue();
268:             try
269:             {
270:                 var cw = Manager.ui != null ? Manager.ui.chatWindow : null;
271:                 if (_renderChatText == null) _renderChatText = AccessTools.Method(typeof(ChatWindow), "RenderText");
272:                 if (cw == null || _renderChatText == null)
273:                 {
274:                     LogError($"chat reply not shown (chatWindow={(cw != null)}, RenderText={(_renderChatText != null)}): {msg}");
275:                     continue;
276:                 }
277:                 _renderChatText.Invoke(cw, new object[] { msg });
278:             }
279:             catch (Exception e)
280:             {
281:                 LogError("chat reply failed: " + msg, e);
282:             }
283:         }
284:     }
